import{_ as t,o as s,c as n,a0 as a}from"./chunks/framework.ChlVJx0I.js";const g=JSON.parse('{"title":"sync internals","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/sync/internals.md","filePath":"extensions/sync/internals.md","lastUpdated":1789578193000}'),o={name:"extensions/sync/internals.md"};function d(i,e,r,c,h,l){return s(),n("div",null,[...e[0]||(e[0]=[a(`<h1 id="sync-internals" tabindex="-1">sync internals <a class="header-anchor" href="#sync-internals" aria-label="Permalink to &quot;sync internals&quot;">​</a></h1><p>The internal reference for the sync extension: the manifest, the merge semantics, the token lifecycle, the Gist backend, and the module map. For the onboarding wizard and the commands, see the <a href="/pi-extensions/extensions/sync/">sync page</a>.</p><h2 id="the-token-lifecycle-adr-0007" tabindex="-1">The token lifecycle (ADR 0007) <a class="header-anchor" href="#the-token-lifecycle-adr-0007" aria-label="Permalink to &quot;The token lifecycle (ADR 0007)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Token form</th><th>How it is managed</th></tr></thead><tbody><tr><td><strong>Managed</strong> (device flow)</td><td>Stored as JSON in <code>&lt;state-dir&gt;/token</code> (mode 600) with <code>accessToken</code>, <code>refreshToken</code>, and expiry. The tool <strong>renews it while it lives</strong>: proactively when a run starts inside the 5-minute skew window, and reactively when a request gets a 401/403 (the request retries once with the fresh token). Bounds: at most one proactive refresh at run start, plus at most one reactive refresh or one device-flow re-run on a mid-operation 401/403; the device flow re-run needs a terminal, so a headless run reports the fix instead of looping.</td></tr><tr><td><strong>Hand-written</strong> (plain text file or <code>PI_SYNC_TOKEN</code>)</td><td>Respected but <strong>never managed</strong>: no refresh, no device flow, no rewrites. A dead hand-written token produces the plain &quot;token rejected&quot; error.</td></tr></tbody></table><p>A 404 (gist not found, not a permission problem) never enters renewal: it is a plain error. In pi, nothing on session start ever triggers the device flow: startup work is read-only.</p><h2 id="what-gets-synced" tabindex="-1">What gets synced <a class="header-anchor" href="#what-gets-synced" aria-label="Permalink to &quot;What gets synced&quot;">​</a></h2><p>The manifest is an owner-only JSON file in the sync state dir (<code>~/.pi/sync/manifest.json</code> by default). It is <strong>default-deny</strong>: only paths matched by an <code>include</code> glob are synced.</p><table tabindex="0"><thead><tr><th>Key</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>v</code></td><td><code>1</code></td><td>Manifest format version.</td></tr><tr><td><code>include</code></td><td><code>.pi/agent/settings.json</code>, <code>.pi/agent/extensions/**</code>, <code>.pi/agent/skills/**</code>, <code>.pi/agent/themes/**</code>, <code>.pi/agent/models.json</code>, <code>.pi/agent/models-store.json</code>, <code>.pi/web-search.json</code>, <code>AGENTS.md</code>, <code>OPINIONS.md</code>, <code>VOICE.md</code></td><td>Globs relative to the home. <code>**</code> crosses directories; <code>*</code> does not; <code>?</code> is one non-<code>/</code> character.</td></tr><tr><td><code>exclude</code></td><td><code>.pi/agent/auth.json</code>, <code>.pi/agent/sessions/**</code>, <code>.pi/agent/npm/**</code>, <code>.pi/agent/git/**</code>, <code>.pi/agent/bin/**</code>, <code>.pi/agent/trust.json</code>, <code>.pi/agent/*-debug.log</code></td><td>Globs that beat every include: credentials, sessions, caches, and logs never sync.</td></tr><tr><td><code>backend</code></td><td><code>github-gist</code></td><td>Registered backend id.</td></tr><tr><td><code>backendOptions.gistId</code></td><td><code>&quot;&quot;</code></td><td>Device-local: the gist id this device syncs. A new device is told the id at init; the shared manifest itself carries none.</td></tr></tbody></table><p>Files that do not match are invisible to the tool - it never reads, hashes, or backs them up. Walking skips symlinks and the directories <code>node_modules</code> and <code>.git</code>.</p><h2 id="merge-semantics" tabindex="-1">Merge semantics <a class="header-anchor" href="#merge-semantics" aria-label="Permalink to &quot;Merge semantics&quot;">​</a></h2><p>The merge is a pure function (<code>extensions/sync/merge.ts</code>) over three snapshots: <strong>base</strong>, <strong>local</strong>, <strong>remote</strong>.</p><ul><li><strong>Base is device-local.</strong> Each device caches the Base of its last sync in <code>&lt;state-dir&gt;/base-state.json</code> (owner-only). The shared base in the gist advances with every push, so a device that has not pulled must merge against the base <em>it last saw</em>, not the newest one - otherwise every quiet file on the stale device reads as &quot;changed by both sides&quot;. After a pull the cache is the newest shared base; after a push it is the base the device just wrote.</li><li><strong>Unchanged + unchanged:</strong> no action.</li><li><strong>One side changed:</strong> take the changed side.</li><li><strong>Both changed, same content:</strong> converged. The file is rewritten with the shared content and its mtime is normalized (no backup).</li><li><strong>Both changed, different content:</strong> conflict. The newer file mtime wins; on an equal mtime the <strong>local</strong> side wins, so a pull never clobbers an edit made at the same second it ran.</li><li><strong>Deleted one side, changed the other:</strong> the change wins. Deleted on both sides: stays deleted.</li><li><strong>New on one side:</strong> appears on the other.</li><li><strong>Not covered by either manifest:</strong> unmanaged. Files the shared tree holds that no manifest pattern covers (for example hand-added in the GitHub UI) never enter the merge: no device applies them locally and they never reach the base state.</li></ul><p>Every file the merge overwrites gets a backup named <code>&lt;path&gt;.&lt;millis&gt;.bak</code> next to it. The collector skips <code>*.bak</code>, so backups never enter a snapshot. The tool never deletes user files that the manifest no longer matches.</p><p>A joining device (init) adopts every manifest-covered shared file it lacks. The tool-managed manifest is never adopted by the merge; the init operation writes it explicitly, which keeps the local copy&#39;s gist id intact.</p><p><strong>Hand-added files are protected.</strong> A gist file the tool never managed (for example one added in the GitHub UI at a path no pattern covers) is never deleted by a push: the backend leaves it in place, and every push reports it, so the user can delete it deliberately in the GitHub UI.</p><h2 id="reference-scanner" tabindex="-1">Reference scanner <a class="header-anchor" href="#reference-scanner" aria-label="Permalink to &quot;Reference scanner&quot;">​</a></h2><p>Before init, pull, and push, the local markdown files are scanned for references to paths outside the manifest: <code>~/...</code> tokens and markdown link targets. The scanner dedupes by (file, resolved path) pair; each distinct uncovered pair produces one warning line. The warnings are advisory: the operation still runs. This implements the spec&#39;s &quot;detect and warn&quot; for cross-references that would dangle after a sync.</p><h2 id="the-gist-backend" tabindex="-1">The Gist backend <a class="header-anchor" href="#the-gist-backend" aria-label="Permalink to &quot;The Gist backend&quot;">​</a></h2><ul><li>One <strong>secret</strong> gist holds the whole tree: one entry per file, plus two tool-managed entries - <code>.pi-sync-manifest.json</code> (the manifest) and <code>.pi-sync-base-state.json</code> (the shared base).</li><li><strong>Limits are enforced locally, before any request:</strong> 20 files max (the gist file cap), 10 MB total (the gist body cap).</li><li><strong>Transport is a seam.</strong> <code>GistTransport</code> is one <code>request</code> function (method, url, headers, optional body). Production uses the global <code>fetch</code> against <code>https://api.github.com</code> (overridable by <code>PI_SYNC_GITHUB_BASE_URL</code>); tests stub it, the CLI E2E stands up a loopback server, and the real API is covered by the opt-in e2e.</li><li><strong>Updates use <code>PATCH /gists/{id}</code>.</strong> The legacy <code>PUT</code> alias is not in the fine-grained PAT endpoint list, and GitHub answers it with a 404 that reads as &quot;gist not found&quot;.</li><li>Every request carries <code>Authorization: Bearer &lt;token&gt;</code>; the token is never logged, and failure reports carry the GitHub message without credentials. A 401/403 on an authenticated request gives the auth session one chance to renew the managed token and retry the request once.</li></ul><h2 id="token-and-state" tabindex="-1">Token and state <a class="header-anchor" href="#token-and-state" aria-label="Permalink to &quot;Token and state&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Location</th><th>Purpose</th></tr></thead><tbody><tr><td><code>~/.pi/sync/token</code> (or <code>$PI_SYNC_STATE_DIR/token</code>)</td><td>The GitHub token, mode 600: managed JSON (device flow) or hand-written plain text. A group/world-readable file produces a warning in every report (CLI and pi commands).</td></tr><tr><td><code>PI_SYNC_TOKEN</code></td><td>Overrides the file for one run. Never managed.</td></tr><tr><td><code>~/.pi/sync/oauth-client.json</code></td><td>The public OAuth client id, written by <code>scripts/setup-sync-wizard.sh</code>.</td></tr><tr><td><code>PI_SYNC_OAUTH_CLIENT_ID</code></td><td>Overrides the client id file for one run.</td></tr><tr><td><code>~/.pi/sync/manifest.json</code></td><td>The device&#39;s manifest copy (carries the local gist id).</td></tr><tr><td><code>~/.pi/sync/base-state.json</code></td><td>The device&#39;s last-synced Base (owner-only).</td></tr><tr><td><code>PI_SYNC_HOME</code> / <code>PI_SYNC_STATE_DIR</code> / <code>PI_SYNC_GITHUB_BASE_URL</code></td><td>Relocate home, state dir, and API base for scripted runs.</td></tr></tbody></table><h2 id="module-map" tabindex="-1">Module map <a class="header-anchor" href="#module-map" aria-label="Permalink to &quot;Module map&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>types.ts</code></td><td>The seams: <code>SyncManifest</code>, <code>Snapshot</code>, <code>BaseState</code>, <code>Backend</code>.</td></tr><tr><td><code>manifest.ts</code></td><td>Manifest parse/validate/serialize, glob matching, <code>walkRoots</code>.</td></tr><tr><td><code>hash.ts</code></td><td>sha256 hex and the strict UTF-8 check.</td></tr><tr><td><code>localfs.ts</code></td><td>Local collect (symlink and dir-name guards), plan apply with backups, manifest + base-state files.</td></tr><tr><td><code>merge.ts</code></td><td>The pure three-way merge.</td></tr><tr><td><code>refs.ts</code></td><td>The cross-reference scanner.</td></tr><tr><td><code>token.ts</code></td><td>Token file: managed JSON vs hand-written plain text, resolution, warnings.</td></tr><tr><td><code>config.ts</code></td><td>The OAuth client id resolution (env wins, then the wizard-written file).</td></tr><tr><td><code>deviceflow.ts</code></td><td>The GitHub OAuth device flow: request code, poll, one retry, persist.</td></tr><tr><td><code>refresh.ts</code></td><td>The token refresh: proactive skew check and the reactive exchange.</td></tr><tr><td><code>auth.ts</code></td><td>The auth session: resolves a token, owns the renewal bounds (one proactive refresh at run start, one reactive renewal per run).</td></tr><tr><td><code>backends.ts</code></td><td>Backend registry.</td></tr><tr><td><code>backends/github-gist.ts</code></td><td>The Gist backend over the <code>GistTransport</code> seam; 401/403 hands back to the auth session for one renewal + retry.</td></tr><tr><td><code>ops.ts</code></td><td>The five operations; one <code>SyncRuntime</code> for CLI and pi.</td></tr><tr><td><code>cli.ts</code> / <code>cli.mjs</code></td><td>The <code>pi-sync</code> CLI (jiti-loaded TS, no build step).</td></tr><tr><td><code>index.ts</code></td><td>The pi extension: <code>/sync</code>, the TUI wizard, the startup notice.</td></tr></tbody></table><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/sync</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                          # no network</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PI_SYNC_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">gist</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt; </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/sync/e2e-gist.mjs</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # opt-in, real GitHub, PAT mode</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">PI_SYNC_OAUTH_CLIENT_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/sync/e2e-gist.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --device-flow</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # opt-in, real GitHub, device flow</span></span></code></pre></div><ul><li><code>manifest.test.ts</code> - glob semantics, validation, canonical serialization.</li><li><code>merge.test.ts</code> - every merge case from the spec table.</li><li><code>refs.test.ts</code> - scanner coverage and caps.</li><li><code>token.test.ts</code> - managed vs hand-written tokens, precedence, warnings.</li><li><code>deviceflow.test.ts</code> - the device flow states (success, one retry on expiry, denial, abort), the refresh paths, and the auth session bounds (hand-written tokens never managed; at most one renewal per run; 404 never renews).</li><li><code>ops.test.ts</code> - the operations on real temp homes against the in-memory fake backend, including the multi-device stale-base scenarios and the consent gates on both init paths.</li><li><code>gist-backend.test.ts</code> - the Gist backend against a stubbed transport.</li><li><code>cli.test.ts</code> - the CLI E2E: a loopback server speaks the Gist API and the OAuth endpoints, two homes sync through the real HTTP stack.</li><li><code>onboarding-e2e.test.ts</code> - the onboarding proof (issue #40): the real CLI in a real terminal (a pty via util-linux <code>script</code>), a loopback stub playing GitHub, the test playing the human (entering the device code by flipping the stub, confirming with y), from a clean home to a joined device, plus the decline path that writes nothing.</li><li><code>e2e-gist.mjs</code> - the opt-in live run against the real GitHub (PAT or device flow mode), timed for human actions; it records the human action count and deletes the gist on exit.</li></ul>`,26)])])}const u=t(o,[["render",d]]);export{g as __pageData,u as default};
